import { expect, test, vi } from 'vitest'
import { middleware } from './middleware'
import { NextRequest } from 'next/server'

test('middleware adds X-Request-Id header and logs pathname', () => {
  const request = new NextRequest('http://localhost:3000/test-path')
  const consoleSpy = vi.spyOn(console, 'log')

  const response = middleware(request)

  expect(consoleSpy).toHaveBeenCalledWith('Request Pathname: /test-path')
  expect(response.headers.get('X-Request-Id')).toBeDefined()
  expect(response.headers.get('X-Request-Id')?.length).toBeGreaterThan(0)
})

